"""Build dependency-free static detail pages and the shared dashboard ledger.
Canonical editable research lives in data/*.json. Run from any directory.
"""
import json, html, re
from pathlib import Path
P=Path(__file__).resolve().parents[1]
def read(n): return json.loads((P/'data'/f'{n}.json').read_text())
H=read('hotels')['hotels']; M=read('michelin'); A=read('activities')['activities']; C=read('costs'); F=read('flags')['flags']; B=read('brief')
D={**B,'hotels':H,'clusters':M['clusters'],'restaurants':M['restaurants'],'activities':A,'costs':C,'flags':F}
(P/'data.js').write_text('/* Generated by scripts/build_pages.py; edit data/*.json instead. */\nwindow.TRIP_DATA = '+json.dumps(D,ensure_ascii=False,indent=2)+';\n')
def e(s):return html.escape(str(s),quote=True)
def link(url,label='Official source'):return f'<a href="{e(url)}" target="_blank" rel="noopener noreferrer">{e(label)} ↗</a>' if url else ''
def blank(s):return e(s) if s != '' and s is not None else '<span class="unknown" title="Not confirmed from the official source">—</span>'
def flags(x):return ' '.join(f'<a class="badge warn" href="flagged.html#{e(i)}">{e(i)}</a>' for i in x.get('flags',[]))
def socials(x):return '<br>'.join(link(u,k) for k,u in x.get('socials',{}).items())
def source_links(x):
 refs=[]
 if x.get('source'): refs.append(link(x['source']))
 refs.extend(link(s['url'],s.get('label','Additional official source')) for s in x.get('secondarySources',[]))
 return '<br>'.join(v for v in refs if v)
NAV=[('index.html','Overview'),('executive-summary.html','Summary'),('hotels.html','Hotels'),('michelin.html','Michelin'),('activities.html','Activities'),('costs-booking.html','Dates & costs'),('questions.html','Questions'),('suggestions.html','Suggestions'),('flagged.html','Review flags'),('sources.html','Sources'),('entry-audit.html','Entry audit')]
def page(file,title,desc,body):
 nav=''.join(f'<a href="{u}"'+(' aria-current="page" class="active"' if u==file else '')+f'>{t}</a>' for u,t in NAV)
 out=f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="theme-color" content="#0f172a"><meta name="description" content="{e(desc)}"><title>{e(title)} · China trip planning desk</title><link rel="stylesheet" href="assets/css/style.css?v=20261126-v3"><script src="assets/js/app.js?v=20261126-v3" defer></script></head>
<body><a class="skip-link" href="#main">Skip to content</a><header class="topbar"><div class="topbar-inner"><a class="brand" href="index.html">中 China trip <small>Evidence-first planning desk</small></a><nav class="mainnav" aria-label="Main navigation">{nav}</nav></div></header>
<main id="main" class="wrap"><section class="hero"><p class="eyebrow">TWO ADULTS · FEB 15–MAR 23, 2027</p><h1>{e(title)}</h1><p>{e(desc)}</p><div class="chips"><span class="chip">Snapshot updated Nov 26, 2026</span><span class="chip">7-night comparison</span><span class="chip">Official facts ≠ 2027 guarantees</span></div></section>
<div class="note">A dash means unverified, not zero. Prices are in CNY unless labelled USD. No hotel has a verified one-hour transit catchment or an official seven-night quote. <a href="flagged.html">See all review flags</a>.</div>{body}</main><footer>ChinaFun2 · 2 adults · Research snapshot, not a booking service. <a href="index.html">Back to dashboard</a> · <a href="research/entry-audit.md">Original entry audit</a></footer></body></html>'''
 (P/file).write_text(out)
def table(id,headers,rows,filter=True,source_policy='official'):
 tool=f'<div class="toolbar"><label for="{id}-search">Search these records</label><input id="{id}-search" data-filter="{id}" type="search" placeholder="City, venue, cuisine or review flag…"><span id="{id}-count" role="status">{len(rows)} of {len(rows)} rows shown</span></div>' if filter else ''
 head=''.join(f'<th scope="col" data-sort><button type="button">{e(h)} <span aria-hidden="true">↕</span></button></th>' for h in headers)
 return tool+f'<p class="table-hint">Scroll horizontally for all columns. Use column buttons to sort; blank values stay last.</p><div class="table-wrap" tabindex="0" role="region" aria-label="{e(id)} comparison"><table id="{id}" data-sortable data-source-policy="{e(source_policy)}"><caption class="sr-only">{e(id)} records with source links and review flags</caption><thead><tr>{head}</tr></thead><tbody>'+''.join('<tr>'+''.join(f'<td>{v}</td>' for v in row)+'</tr>' for row in rows)+'</tbody></table></div>'
cityrows=[[e(x['city']),e(x['edition']),e(x['count']),e(x['detail']),e(x['comparability']),link(x['source'])] for x in M['clusters']]
summary='''<div class="grid"><article class="card"><h2>Provisional choice: Shanghai</h2><p>Start with one city for seven nights: Mon Feb 15 → Mon Feb 22. The existing Shanghai restaurant and sightseeing shortlist is the deepest in this project. This is a planning recommendation, not proof that it is the cheapest or most transit-efficient base.</p></article><article class="card"><h2>Keep three alternatives open</h2><p>Beijing for imperial culture, Guangzhou for Cantonese dining, Chengdu for Sichuan food and pandas. Choose by your priorities before paying deposits; no comparable full-trip cost or hotel route ranking is available.</p></article><article class="card"><h2>Knowns & unknowns</h2><p>Two adults, private ensuite room, Queen or larger, preferred start Feb 15–18; exact duration and budget unresolved. Airfare, official room totals, restaurant bills and transit catchments are not priced or qualified.</p></article></div>'''
summary+=table('cities',['City','Edition / scope','Starred venues','Breakdown','Decision context','Official source'],cityrows)
summary+='''<h2 class="section">A practical seven-night draft — not a qualified transit itinerary</h2><div class="card"><ol><li>Mon Feb 15: arrival, check-in, light Bund / Nanjing Road walk. Avoid Monday-closed museums and Yu Garden.</li><li>Tue Feb 16: Shanghai Museum People’s Square after checking the day/evening session and any reservation notice; individual walk-in rules have exceptions. Flexible neighborhood dinner.</li><li>Wed Feb 17: Yu Garden daytime and old-town walk; do not confuse bazaar/night-tour tickets with garden admission.</li><li>Thu Feb 18: neighborhood culture and one prebooked tasting-menu dinner, if budget and dietary requirements fit.</li><li>Fri Feb 19: Shanghai Tower, subject to visibility, ticket selection and route confirmation.</li><li>Sat Feb 20: flexible food day; event closures and crowds require a fresh venue-calendar check.</li><li>Sun Feb 21: optional exhibition or neighborhood walk; leave packing and transfer time.</li><li>Mon Feb 22: checkout/departure. No paid intercity side trip assumed.</li></ol><p>All hotel-to-site and hotel-to-restaurant travel remains unverified. See <a href="activities.html">official activity schedules</a> and <a href="michelin.html">restaurant sources</a> before assigning reservations.</p></div>'''
summary+='<div class="note blue">Official Spring Festival break: Feb 5–13, 2027; Feb 14 is a makeup workday. Starting Feb 15 is after the national holiday, not proof of lower prices or fewer visitors. '+link(C['stay_options'][0]['source'],'State Council holiday notice')+'</div>'
page('executive-summary.html','The decision brief','Four candidate cities, one provisional seven-night base, and the evidence still needed before booking.',summary)
rows=[]
for x in H:
 rows.append([e(x['city'])+'<br><strong>'+e(x['name'])+'</strong><p>'+e(x['area'])+'</p>',blank(x['rank']),blank(x['bed']),blank(x['bath']),e(x['evidence'])+'<p>'+e(x['amenities'])+'</p>',blank(x['total']),blank(x['transit']),blank(x['activityTransit']),link(x['roomSource'],'Official room/property page')+'<br>'+link(x['bookSource'],'Official booking')+'<p>'+flags(x)+'</p>'])
page('hotels.html','Hotel candidates — not yet ranked','Private ensuite + Queen/King for two is the required fit, not an assumption. No route-based or price-based winner is established.',table('hotels',['City / candidate','Verified rank','Bed confirmed','Private bath confirmed','Official room evidence / amenities','Official 7-night 2027 total','Michelin ≤60m count','Activities ≤60m routes','Sources / flags'],rows)+'<div class="note">Only room descriptions explicitly retained from official pages are shown. Blank bed/bath fields require category-level confirmation. No secondary “from” rate, nightly × 7 proxy or district estimate qualifies. <a href="costs-booking.html">Compare date windows and booking checkpoints</a>.</div><p><a href="data/hotels.json">Download hotel JSON</a></p>')
rows=[]
for x in M['restaurants']:
 rows.append([e(x['city'])+'<br><strong>'+e(x['name'])+'</strong>',e(x['status']),e(x['cuisine']),blank(x['guideBand']),blank(x['coupleTotal']),blank(x['hours'])+'<p>'+e(x['exceptions'])+'</p>',link(x['guide'],'MICHELIN venue')+'<br>'+link(x['venue'],'Venue / menu')+'<p>'+flags(x)+'</p>',socials(x)])
page('michelin.html','Michelin restaurants','Star distinctions are separate from Bib Gourmand and Selected. Guide price symbols are not cash meal prices.',table('restaurants',['City / restaurant','Distinction / edition','Cuisine','Guide band','Official published menu basis · two adults','Hours / closures / exceptions','Evidence / flags','Discovery links'],rows)+'<div class="note">Taian Table: ¥5,176 / ¥5,776 = two published ¥2,588 / ¥2,888 menus before supplements; not a guaranteed 2027 bill. Booking up to 90 days; ¥2,000 deposit per person. Confirm fee/tax inclusion and cancellation terms. <a href="flagged.html#R04">Ultraviolet is excluded from the bookable shortlist</a>.</div><div class="note">Creator videos are non-official discovery links. For the few direct links, title/channel/date were checked from page metadata, but the videos were not watched; do not use them to establish current menu, hours, star status or 2027 pricing.</div><p><a href="data/michelin.json">Download restaurant and city JSON</a></p>')
rows=[]
for x in A:
 rows.append([e(x['city'])+'<br><strong>'+e(x['name'])+'</strong>',blank(x['schedule']),blank(x['cost']),blank(x['transit']),e(x['exception']),source_links(x)+'<p>'+flags(x)+'</p>',socials(x)])
page('activities.html','Culture & sightseeing','Regular schedules, Monday/Tuesday closure traps and two-adult ticket products; no hotel-to-site route is qualified yet.',table('activities',['City / activity','Published regular hours','Two-adult cost / product','Door-to-door public transit','Exceptions / booking caveats','Official source / flags','Discovery links'],rows)+'<div class="note">Direct creator videos are non-official past-visit discovery only. Their title/channel/date metadata was checked, but footage was not watched; videos do not establish current schedules, ticket prices, Michelin status or 2027 operations. Search shortcuts remain unverified.</div><p><a href="data/activities.json">Download activity JSON</a></p>')
body='<div class="grid"><article class="card"><h2>Today: 81–84 days out</h2><p>November 26, 2026 is 81 days before Feb 15 and 84 before Feb 18. Compare refundable official room totals now; the 60–90-day span is a monitoring interval, not a proven cheapest window.</p></article><article class="card"><h2>Track like-for-like totals</h2><p>Two adults, one Queen+/King room with private ensuite, seven nights, exact currency, all taxes/fees, same meal inclusion and cancellation terms. Record cancellation cutoff in property local time. Airfare, visas, food and transport are separate, currently unpriced.</p></article></div>'
body+=table('stays',['Check-in','Check-out','Nights','Official hotel total · two adults','Date context / flags'],[[e(x['checkin']),e(x['checkout']),e(x['nights']),blank(x['official_total']),link(x['source'],'Official holiday context')+'<br>'+flags(x)] for x in C['stay_options']])
body+='<h2>Target booking / recheck dates</h2><p>These are calendar-arithmetic checkpoints only—not rate quotes or evidence of an optimal booking lead time. Obtain dated totals from each selected hotel’s own official booking page.</p>'
body+=table('checkpoints',['Lead days','For Feb 15 start','For Feb 18 start','Proposed action','Calendar arithmetic / flags'],[[e(x['lead_days']),e(x['target_start']),e(x['target_end']),e(x['action']),flags(x)] for x in C['booking_windows']],source_policy='calendar-arithmetic')
body+='<details><summary>Quarantined aggregator observations — not bookable quotes</summary><p>Prior traveldeals.com research observations lack exact stay, room, tax and cancellation metadata. They cannot establish 2027 totals, savings or an optimum booking window. To avoid implying comparable rates, the numbers are excluded from these decision tables and retained only in the labelled audit records in the JSON download. Official quote columns above remain empty. See <a href="flagged.html#B01">B01</a> and <a href="flagged.html#B02">B02</a>.</p></details><p><a href="data/costs.json">Download dates / costs and quarantined observations (JSON)</a></p>'
page('costs-booking.html','Dates, costs & booking','Useful calendar checkpoints without a fabricated cheapest day or an unsupported all-in trip budget.',body)
page('questions.html','Questions & missing information','Resolve these before paying non-refundable deposits. Never post passport numbers or sensitive documents.', ''.join('<article class="card question"><h2>'+e(x['q'])+'</h2><span class="badge warn">'+e(x['state'])+'</span><p><strong>Known:</strong> '+e(x['answer'])+'</p><p><strong>Next:</strong> '+e(x['next'])+'</p></article>' for x in B['questions'])+'<div class="note">Entry cannot be inferred from where you live. <a href="entry-audit.html">Read the official-source entry audit</a>.</div>')
page('suggestions.html','Improve the decision','Actionable research and workflow proposals; nothing here purchases or reserves travel.', ''.join('<article class="card question"><h2>'+e(x['title'])+'</h2><p>'+e(x['desc'])+'</p><p>Value: '+e(x['impact'])+' · Effort: '+e(x['effort'])+'</p></article>' for x in B['suggestions'])+'<article class="card question"><h2>Capture a route matrix and price log</h2><p>Choose two finalists in one city. Record exact room quotes and complete weekday/weekend public-transit routes to every shortlisted venue. Only then calculate a ≤60-minute count or rank. Search and sortable tables are available now; saved comparisons and live route integrations remain proposals.</p></article>')
page('flagged.html','Flagged for review','Every unverified price, route, schedule and scope issue stays visible. Publication can proceed; bookings still need checks.', ''.join(f'<article class="card question" id="{e(x["id"])}"><span class="badge warn">{e(x["status"])}</span><h2>{e(x["id"])} · {e(x["scope"])}</h2><p>{e(x["issue"])}</p><p><strong>Next:</strong> {e(x["next"])}</p>{link(x["source"])}</article>' for x in F))
unique={}
for group in [H,M['restaurants'],A]:
 for x in group:
  if x.get('official_url'): unique[x['official_url']]=x['name']
  for extra in x.get('secondarySources',[]): unique[extra['url']]=x['name']+' · '+extra.get('label','additional official source')
for x in M['clusters']:unique[x['source']]=x['city']+' selection release'
for x in C['stay_options']:
 if x.get('source'): unique[x['source']]='2027 State Council holiday notice / date context'
for x in F: unique.setdefault(x['source'],x['scope'])
page('sources.html','Sources & verification method','Official source links sit alongside each record; a linked homepage does not verify every blank metric.', '<div class="card"><h2>Evidence levels</h2><ol><li>Official property, venue, government or MICHELIN pages support only the stated information.</li><li>Current menu arithmetic is separate from a date-specific 2027 bill.</li><li>Aggregator observations are quarantined, never copied into official quote cells.</li><li>Direct creator videos are non-official past-visit discovery links; some page metadata was checked, but footage was not watched. Other social searches are discovery only, not evidence or endorsements.</li><li>City totals are not a route-verified hotel catchment. Blank is not zero.</li></ol><p><a href="RESEARCH_REVIEW.md">Full reconciliation audit</a> · <a href="research/entry-audit.md">Original entry audit</a> · <a href="COORDINATION.md">Coordination history</a></p></div>'+table('sources',['Record / scope','Official source'],[[e(n),link(u)] for u,n in unique.items() if u]))
# Render the original Markdown audit with a deliberately small, escaped renderer.
def inline(s):
 s=e(s);s=re.sub(r'\[([^\]]+)\]\((https://[^\s)]+)\)',r'<a href="\2" target="_blank" rel="noopener noreferrer">\1</a>',s);return re.sub(r'\*\*([^*]+)\*\*',r'<strong>\1</strong>',s)
parts=[]; labels=None
for line in (P/'research/entry-audit.md').read_text().splitlines():
 if line.startswith('#'):
  n=min(len(line)-len(line.lstrip('#')),4);parts.append(f'<h{n}>'+inline(line.lstrip('# '))+f'</h{n}>');labels=None
 elif line.startswith('|'):
  cells=[v.strip() for v in line.strip('|').split('|')]
  if all(re.fullmatch(r'[:\- ]+',v) for v in cells):continue
  if labels is None:labels=cells;continue
  parts.append('<section class="audit-row"><h3>'+inline(cells[0])+'</h3><dl>'+''.join('<dt>'+inline(label)+'</dt><dd>'+inline(value)+'</dd>' for label,value in zip(labels[1:],cells[1:]))+'</dl></section>')
 elif line.strip():parts.append('<p>'+inline(line)+'</p>');labels=None
page('entry-audit.html','Entry, health & eligibility audit','Independent audit retained from session b679d5a6; personal eligibility remains unresolved.', '<div class="card audit">'+''.join(parts)+'</div>')
print(f'Built 10 detail pages; {len(H)} hotels, {len(M["restaurants"])} restaurants, {len(A)} activities, {len(F)} flag groups.')
